CREATE TABLE IF NOT EXISTS legal_documents (
  id TEXT PRIMARY KEY, title TEXT NOT NULL, original_title TEXT, document_type TEXT NOT NULL, year_bs INTEGER NOT NULL, year_ad INTEGER NOT NULL, total_pages INTEGER NOT NULL, nodes JSONB NOT NULL, source_filename TEXT NOT NULL
);

INSERT INTO legal_documents (id,title,original_title,document_type,year_bs,year_ad,total_pages,nodes,source_filename) VALUES ($CODEx5aaf160c6f$doc_land_survey_and_measurement_act_2019_1963_2019_land_survey_and_me$CODEx5aaf160c6f$,$CODEx72f68405b2$Land (Survey and Measurement) Act, 2019 (1963)$CODEx72f68405b2$,NULL,$CODEx76f3b5a717$act$CODEx76f3b5a717$,2019,1963,21,$CODEx83f47c867b$[{"tier": 1, "nodeType": "preamble", "identifier": "Preamble", "title": "Introductory matter", "content": "www.lawcommission.gov.np\nLand (Survey and Measurement) Act, 2019 (1963)\nDate of authentication and publication\n2019.12.30 (12 April 1963)\nAmendments", "children": []}, {"tier": 1, "nodeType": "section_group", "identifier": "Sections", "title": "Sections", "content": null, "children": [{"tier": 2, "nodeType": "section", "identifier": "1", "title": "Land (Survey and Measurement) 2024.7.6 (23 Oct.1967)", "content": "(First Amendment) Act, 2024", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "2", "title": "Land (Survey and Measurement) 2029.6.5 (21 Sept. 1972)", "content": "(Second Amendment) Act, 2029", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "3", "title": "Land (Survey and Measurement) 2033.7.4 (20 Oct. 1976)", "content": "(Third Amendment) Act, 2033", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "4", "title": "Land (Survey and Measurement) 2035.5.21 (6 Sept.1978)", "content": "(Fourth Amendment) Act, 2035", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "5", "title": "Land (Survey and Measurement) 2036.8.5 (21 Nov. 1979)", "content": "(Fifth Amendment) Act, 2036", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "6", "title": "Land (Survey and Measurement) 2046.7.11 (27 Oct. 1989)", "content": "(Sixth Amendment) Act, 2046", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "7", "title": "Administration of Justice Act, 2048 2048.2.16 (30 May 1991)", "content": null, "children": []}, {"tier": 2, "nodeType": "section", "identifier": "8", "title": "Land (Survey and Measurement) 2049.6.28 (14 Oct. 1992)", "content": "(Seventh Amendment) Act, 2049", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "9", "title": "Land (Survey and Measurement) 2057.3.7 (21 June 2000)", "content": "(Eighth Amendment) Act, 2056\n1\nwww.lawcommission.gov.np", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "10", "title": "Republic Strengthening and Some Nepal 2066.10.7 (21 Jan. 2010)", "content": "Laws Amendment Act, 2066\nAct number 51 of the year 2019 (1963)\nAn Act made to provide for survey and measurement of lands\nPreamble: Whereas, it is expedient to make arrangements for the survey and\nmeasurement of lands and for determining their grade in order to maintain cordial\nrelations between people of different classes, communities or regions in\n……Nepal1 and to maintain convenience of the citizens of Nepal generally;\nNow, therefore, His Majesty King Mahendra Bir Bikram Shah Dev has\nenacted this Act in accordance with Article 93 of the Constitution of Nepal.", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "1", "title": "Short title, extension and commencement: (1) This Act may be called", "content": "as the \"Land (Survey and Measurement) Act, 2019 (1963).”\n(2) This Act shall extend throughout Nepal.\n(3) This Act shall come into force immediately.", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "2", "title": "Definitions: Unless the subject or the context otherwise requires, in this", "content": "Act:\n(a) \"land\" means all categories of land, including those with buildings,\ngardens, trees, factories, lakes, ponds etc.;\n(a1)2 \"survey and measurement\" means the act of collecting data related to\nlandowners and tenants, preparing maps of lands, ascertaining the\narea of lands, categorizing the grades of lands or registering lands\n1\nAmended by the Republic Strengthening and Some Nepal Laws Amendment Act, 2066.\n2 Amended by the Eighth Amendment.\n2\nwww.lawcommission.gov.np\nwith the field book on the basis of maps or records, and this terms\nincludes the act of carrying out an aerial survey, establishing\ncontrolling points for survey and making cadastral survey at various\nscale (Man) and publishing maps;\n(a2)3 \"registration record\" means the landowner registration record so\nprepared on the basis of the map and field book prepared following\nthe survey and measurement of a land as to clearly indicating, inter\nalia, the landholder, tenant, plot, area and type or grade of the land;\n(a3)4 \"border\" means a border line determining the boundary between two\ndifferent pieces of land;\n(a4)5 \"plot\" means a piece of land that has boarder in all four sides and has\nsimilarity in right, possession and grade in each place;\n(b)6 \"landholder\" means a person who has right to be a landowner of/in a\nland in accordance with the prevailing Nepal law;\n(c)7 \"tenant\" means a person who cultivates a land belonging to other\nlandholder through the labour of him or her or of his or her family\nafter getting the land for cultivation on any condition;\n(d)8 \"Patuwari\" means any persons who maintain records of lands or\nhomesteads and recover land-revenue or other tariff in accordance\ntherewith;\n(e) \"government land\" means the land where there exit roads, railway,\ngovernment building or office and this expression also includes\nforest, shrubs, jungle, river, streams, Nadi Ukas, lake, pond and\n3 Inserted by the Sixth Amendment.\n4 Inserted by the Seventh Amendment.\n5 Inserted by the Seventh Amendment.\n6 Amended by the Second Amendment.\n7 Amended by the Second Amendment.\n8 Amended by the Second Amendment.\n3\nwww.lawcommission.gov.np\nridge thereof, main canal (Nahar), water course (Kulo), (Barron)\nAilani, Parti and other types of land, Bhir, Pahara, Dagar, shore\n(Bagar) which is under the control of Government and such other\nlands as a Government land as prescribed by Government of Nepal\nby a Notification in the Nepal Gazette.\n(f)9 \"public land\" means and includes roads, wells, water conduits,\nshores, ponds and banks thereof, exits for chattels, pasture lands,\ngraveyards, burial sites, inns, Pauwas, Dewals, religious meditation\nsites, memorials, temples, shrines, Chowk, Dawali, sewerage,\nChautaro, lands where fairs, markets and public entertainment or\nsports sites are located, which been used publically but nor\npersonally since ancient times, and such other lands as prescribed to\nbe the public land by the Government of Nepal, by a notification in\nthe Nepal Gazette; and\n(g) \"prescribed\" or \"as prescribed\" means prescribed or as prescribed in\nthe rules framed under this Act.", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "3", "title": "Power to make survey and measurement of lands: (1)10 The", "content": "Government of Nepal may issue an order to make survey and measurement\nof lands in all or any places within……Nepal11.\n(2) The prescribed authority shall carry out the function as referred\nto in Sub-section (1).\n(3)12 Any station may be established on any land and any\nmeans/equipment of survey may be used, without any control, for the\npurpose of making survey and measurement of lands.\n9 Amended by the Eighth Amendment.\n10 Amended by the Eighth Amendment.\n11 Amended by the Republic Strengthening and Some Nepal Laws Amendment Act, 2066\n12 Amended by the Second Amendment.\n4\nwww.lawcommission.gov.np\n(4) 13 After the issuance of the order as referred to in Sub-section (1),\nthe General Survey Office (Naapi Goswara)14 responsible for making\nsurvey and measurement shall give a notice to the Land-Revenue Office15\nin the concerned district, indicating the date of commencement of survey in\nthe area to be surveyed and measured, and for the provision of records\nrequired for that act.\n(5) 16 If it appears or is informed that there is any mistake or error\nin the act done by the authority making survey and measurement,\nascertaining the area thereof and making entry or registration in the field\nbook, the survey officer shall make necessary examination and make, or\ncause to be made, necessary correction prior to the distribution of\nlandownership registration certificates pursuant to Sub-section (1) of\nSection 8; and departmental action shall be taken against the employee who\nmakes such a mistake or error knowingly.\n(6) 17The prescribed authority shall update, as prescribed, the map\nrecords prepared upon survey and measurement made pursuant to Sub-\nsection (1).\n3A.18 General duties of Jimidar, Patuwari: (1) Within the time-limit\nspecified by the Land-Revenue Office19 in the concerned district, the\nJimidar, Patuwari shall prepare records setting out detailed description of\nthe lands the records of which are in his or her custody including the plot\nnumbers of lands and hand over the same to the concerned Land-Revenue\nOffice20.\n13 Amended by the Second Amendment.\n14 Amended by the Sixth Amendment.\n15 Amended by the Eighth Amendment\n16 Inserted by the Seventh Amendment.\n17 Inserted by the Seventh Amendment.\n18 Inserted by the Second Amendment.\n19 Amended by the Eighth Amendment.\n20 Amended by the Eighth Amendment.\n5\nwww.lawcommission.gov.np\n(2) If the act of making survey, mapping or establishing control\npoint locations commences in the concerned area of their area21 (Mauja),\nthe Jimidar, Patuwari or their representatives shall make presence and\nassistance as and when so required by the survey team22 from the\ncommencement of that act to the end thereof.\n3B. 23 Details to be provided: The Land-Revenue Office and concerned body\nshall provide such records and other documents as required for the survey\nand measurement to the concerned General Survey Office or Survey Office\nprior to the commencement of the survey and measurement.", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "4", "title": "24 Method of determining area of land: (1) In determining the area of", "content": "land surveyed and measured, the area shall be determined at the rate of Ten\nThousand square meters equal to one hectare, and in preparing registration\nrecord, the record shall state both hectare and square meters. In so\nmentioning square meters, up to Two digits after decimal point of square\nmeters shall be mentioned.\n(2)The Land Revenue Office shall convert the area of the land, of\nwhich registration record has been maintained in Bigaha or Ropani, upon\nbeing surveyed and measured, prior to the commencement of this Section,\ninto hectare and square meters.", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "5", "title": "25 Demarcation of border, boundary of Village Development", "content": "Committee or Municipality or Ward: In surveying and measuring\npursuant to this Act, the border, boundary of the area or ward of the Village\nDevelopment Committee or Municipality to be surveyed shall be\ndemarcated prior to making survey of the Village Development Committee\n21 Amended by the Seventh Amendment.\n22 Amended by the Third Amendment.\n23 Inserted by the Eighth Amendment.\n24 Amended by the Seventh Amendment.\n25 Amended by the Third Amendment.\n6\nwww.lawcommission.gov.np\nor Municipality, such survey shall then be made. If in demarcating the\nborder, boundary, there arises any dispute as to the border of a zone or\ndistrict as well, the border, boundary shall be demarcated in accordance\nwith the decision of the prescribed authority or committee. If it appears that\nit shall take time to decide the border, boundary subject to dispute, survey\nwork shall continue and be completed by setting aside the registration of\nthose plots of the border, boundary subject to dispute.\nProvided that, if the survey of the whole district, Village\nDevelopment Committee, Municipality or Ward is not made but that of\nsome parts only is to be made, it is not required to demarcate the border,\nboundary pursuant to this Section.\n5A. 26 …………………..", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "6", "title": "To give notice and commence operation after entering into land:", "content": "(1) If it is necessary to establish a control point station in any land or to\nsurvey and measure any land, a notice shall be given to the landholder,\ntenant of the land where the control point station is to be established or\nwhich is to be surveyed and measured, neighbors, concerned Jimidar,\nPatuwari and Village Development Committee or Municipality prior to at\nleast Fifteen days.\nExplanation: In giving a notice to any landholder, tenant,\nneighbour, Jimidar and Patuwari for the purposes of this Sub-section,\naffixation of the notice of that matter unto main places of movement of\ngeneral public of the area of the land where such control point station is to\nbe so established or which is to be so surveyed and measured or of the area\nwhere the landholder or the tenant is residing shall be sufficient.\n26 Deleted by the Eighth Amendment.\n7\nwww.lawcommission.gov.np\nProvided that, a notice in writing shall be given to the Village\nDevelopment Committee or Municipality.\n(2) In establishing a control point station in any land or surveying\nand measuring any land, such station or survey and measurement may be\nestablished or made in presence of the landholder, his or her representative,\ntenant, concerned Jimidar, Patuwari, neighbour and also a representative of\nthe concerned Village Development Committee or Municipality.\nProvided that, if any landholder or his or her representative, the\ntenant cultivating the land or neighbor does not show up within the time-\nlimit specified in the notice as referred to in Sub-section (1), the control\npoint station may be established or survey and measurement made in\npresence of the Jimidar of the area where that land is situated or his or her\nrepresentative, Patuwari or representative of the concerned Village\nDevelopment Committee or Municipality.\n(3) In establishing a control point station in any land or surveying\nand measuring any land, such permanent or temporary landmarks,\nmonuments or bacons may be placed or installed as may be necessary for\nthat act and the bushes or branches of any tree may be cut off or cleared for\nhaving the view of landscape.\n(4) If any control point station is established in any land, the record\nshall also state the area of land covered by that station, and the\nlandownership registration certificate of the landholder of the land and the\ntilling slip of tenant, if any, shall also state that matter.\nExplanation: The term \"control point station\" means and includes\nan area of up to 1.55 meters on all sides of the landmark in the centre.\n8\nwww.lawcommission.gov.np\n(5)27In the course of surveying and measuring, the landholders shall\nsend certificate of his or her ownership and possession of the land\npersonally or through his or her representative and get his or her land\nregistered. A landholder who has since long past (ancient times) owned,\npossessed and cultivated a land without any evidence, registration and\npayment of land-revenue,28 except a barren land, public land……………29\nand a land within the forest boundary as determined, shall also get the land\nregistered. If such a landholder shows up go get such a land registered on\nthe basis of such ownership and possession since long past (ancient times),\nthe survey team shall affix a notice onto main places of frequent movement\nof people including the tenant and neighbours of the land, also indicating\nthe name of the Village Development Committee or Municipality where the\nland so requested for registration is situated and the boundaries of ward and\nthe name and address of the person showing up for such registration and\nstating that any one may make a complaint on that matter with the survey\nteam within Twenty One days of the affixation of the notice, and shall also\ngive a notice in writing to the local Village Development Committee or\nMunicipality. If no complaint is made, the land shall be registered in the\nname of that landholder by the survey team if the land is outside the\nmunicipal area and by the General Survey Office if it is a house and land\nwhich is within the municipal area and occupied oneself without any\nevidence. If a complaint is made, the survey team, if the land is outside the\nmunicipal area, and the general survey office, if it is a house and land\nwhich is within the municipal area and occupied oneself without any\nevidence, shall carry out public inquiry and necessary examination and\nmake a submission, accompanied by its opinion, to the committee or\n27 Amended by the Third Amendment.\n28 Amended by the Fourth Amendment.\n29 Deleted by the Sixth Amendment.\n9\nwww.lawcommission.gov.np\nauthority designated by the Government of Nepal, and shall act as\nsanctioned.\n(5a)30 If a person obtains the ownership of a house and land of\nwhich land-revenue is not maintained through a deed executed at household\nand has continuously possessed the house and land at least since Fifteen\nyears ago considering that he or she has right in the house and land and any\ncomplaint has not been made on that deed in any court during that period,\nin the course of surveying and measuring the land, the deed shall be\nrecognized as a valid deed despite that it has not been registered and such a\nhouse and land shall be registered in the name of that landholder, and the\nprovision contained in Sub-section (7) shall not apply in this respect.\n(5b) 31 In surveying and measuring a house and land on the ground\nfloor and upper floors or on the same floor, owned by different persons,\nsuch a house and land shall be registered separately in the name of the\nhouse and land holders having separate ownership.\n(5c) 32 If the concerned person makes a claim in writing, along with\nthe evidence, over a land which is registered, and land revenue of which is\nmaintained, in his or her name, which has been owned and possessed by\nhim or her and which contains private forests and shrubs, such a land shall\nbe registered in the name of the concerned landholder in accordance with\nthe decision made by the committee formed pursuant to Section 11B. after\nmaking necessary examination into the matter.\n(5d) 33 In making entry or registration in the field book of a land\nupon surveying it in an area where re-survey and measurement has been\nmade, the previous map and registration record prepared upon making\n30 Inserted by the Fourth Amendment.\n31 Inserted by the Fourth Amendment.\n32 Inserted by the Seventh Amendment.\n33 Inserted by the Seventh Amendment.\n10\nwww.lawcommission.gov.np\nsurvey and measurement in the past shall be looked into and verified, and\nthe description thereof shall be mentioned in the evidence column of the\nfield book.\n(6) In the case of a landholder and tenant who do not get their land\nregistered or send their representative either in the course of making survey\nand measurement pursuant to Sub-section (5), a notice shall be published\nfor the second time in the concerned Village Development Committee or\nMunicipality, thereby giving a time-limit of a maximum of Fifteen days for\nthem to show up for the registration of their land. If the evidence of title\n(ownership and possession) of the landholder and the tenant who appears to\nhave the land registered within the said time-limit is verified or if the\nlandholder of any land which is not registered or on which no land\nrevenue/tax is being paid appears to have his or her land registered on the\nbasis of possession, the prescribed authority may, upon conducting\nnecessary inquiry, register such a land after collecting a fine of Five\nRupees.\n……………….34\n(6a) 35 The prescribed authority may, upon verifying the details\nmentioned in the previous records, and in presence of one representative of\nthe Ward Committee, register the land of a landholder who neither appears\neven within the time-limit given for the second time pursuant to Sub-\nsection (6) nor sends his or her representative. The landholder who is not\nsatisfied with the registration so made may file a complaint in the Court\nwithin Six months after the date of knowledge of that matter.\n34 The proviso deleted by the Sixth Amendment.\n35 Amended by the Eighth Amendment.\n11\nwww.lawcommission.gov.np\n(7) 36 If a dispute relating to the ownership of any land arises\nbetween Two or more persons while it is being surveyed and measured, the\nprescribed authority shall examine the evidence presented by both parties\non the matter, make a decision to have the land registered on a provisional\nbasis on the name of the party whose evidence seems to be stronger until a\nfinal decision is made by the Court, and give an evidence to that effect to\nthe concerned party. If the unsatisfied party does not make a complaint in\nthe Court against that decision within Thirty Five days, that decision shall\nbe final and the land shall be registered accordingly in the name of the\nconcerned person. If a complaint is made, the land shall be registered in\naccordance with the final decision made by the Court.\n(8) 37 ………………\n(9) 38 If, in making re-survey and measurement of land in a place\nwhere the lands have already been surveyed and measured and registration\nrecords thereof have been prepared pursuant to this Act, a dispute arises\nbetween two or more persons in relation to the title to any land as\nmentioned in the previous registration records, the prescribed authority\nshall register the land by verifying the previous registration records. 39\n6A. 40 ………………\n6B. 41 Relating to registration of omitted land (Chhut Jagga): (1)\nNotwithstanding anything contained in the prevailing law, if, in the course\nof surveying and measuring land, the survey and measurement of any land\nis omitted or despite being surveyed and measured its registration is\nomitted, the concerned person may make an application, accompanied by\n36 Amended by the Third Amendment.\n37 Deleted by the Eighth Amendment.\n38 Inserted by the Sixth Amendment.\n39 Amended by the Eighth Amendment.\n40 Deleted by the Eighth Amendment.\n41 Inserted by the Eighth Amendment.\n12\nwww.lawcommission.gov.np\nsuch documents as required for the survey and measurement of such a land,\nto the prescribed authority.\n(2) If an application is made pursuant to Sub-section (1), the\nprescribed authority shall submit the application to the prescribed\ncommittee and shall do in accordance with the recommendation of that\ncommittee.\n(3) If an application is not made pursuant to Sub-section (1), after\nSixty days of the date of distribution of the land ownership registration\ncertificates of that area, such a land shall be registered as a government or\npublic land and records thereof shall be maintained accordingly.\n(4) After the commencement of the act of survey and measurement\nin any area pursuant to Sub-section (1), the Land Revenue Office shall send\nthe record file relating to the registration of omitted land to the concerned\nGeneral Survey Office for necessary action.\n6C. 42 Registration of land possessed upon encroachment: Despite that any\nland measured and surveyed as a government or public land in the past\nbeing cultivated, tilled or possessed by any person upon encroaching and\nmaking a building there, such a land shall be registered as a government or\npublic land in the course of making survey and measurement.\n6D. 43 Power to correct registration records: (1) Notwithstanding anything\ncontained in the other Sections of this Act, if the existing road or water\ncourse changes or the existing road or water course can no longer be used\nbecause the concerned person has left his or her land for a road or water\ncourse and so expanded the road or water course and the existing\nregistration records so differ, and an application is made to the prescribed\nauthority for making correction in the records, the concerned General\n42 Inserted by the Eighth Amendment.\n43 Inserted by the Eighth Amendment.\n13\nwww.lawcommission.gov.np\nSurvey Office shall submit the application to the prescribed committee and\ncorrect and adjust the records by registering the road or water course\nadjoining the land of the applicant in the name of the concerned person, in\naccordance with the recommendation of that committee.\n(2) If, in preparing the registration records pursuant to this Act, if\nthere is any error in the name, surname, address, age of any landholder or\nname of his or her father and grandfather, plot number, area or type of the\nland, the concerned authority shall, upon making necessary inquiry, adjust\nthe registration records.", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "7", "title": "44 In the case of alteration in area of land: (1)……..45 If, in the course of", "content": "making survey and measurement of any land, its area becomes more or less\nthan the previous area, that area of the land as set accordingly shall be\nmaintained in the name of the concerned landholder.\n(2) 46 If the land of any person is adjoining a government or public\nland, the survey and measurement of the land shall be made on the basis of\nthe previous registration records or evidence, if any available, and failing\nsuch records or evidence, such survey and measurement shall be made by\nsetting the area on the basis of the borders as recommended by the\nchairperson of the concerned war of the concerned Village Development\nCommittee or Municipality and at least two nearby neighbors. In so setting\nthe area, if the area of the land of the person adjoining the government or\npublic land is altered, a submission shall be made to the prescribed\ncommittee, and survey and measurement of land shall be made by setting\nthe area as recommended by that committee.\n44 Amended by the Eighth Amendment.\n45 Deleted by the Eighth Amendment.\n46 Amended by the Eighth Amendment.\n14\nwww.lawcommission.gov.np\n(3) 47…………………..\n(4) After the submission of registration records according to the area\nset by the survey and measurement to the land revenue office, the\nconcerned landholder shall pay the land revenue or tax accordance to the\nregistration records.", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "8", "title": "48 To obtain registration certificate: (1) 49 After the completion of the act", "content": "of survey and measurement and preparation of registration records, the\nprescribed authority shall prepare land ownership registration certificates,\nas an evidence of ownership in the lands as set forth in the registration\nrecords, and give such certificate to the concerned landholders or their\nrepresentatives.\n(1a) 50 In the case of separate ownership on the ground floor or upper\nfloor or the same floor of any building, separate land ownership registration\ncertificates shall be prepared in relation to the floors under such separate\nownership and given to the concerned landholders or their representatives.\n(2) If a person does not obtain the land ownership registration\ncertificate pursuant to Sub-section (1), the person may make a complaint to\nthe prescribed authority within Sixty days51 after the date of the\ncommencement of distribution of land ownership registration certificates in\nthe same area or if a person who obtains the land ownership registration\ncertificate but is not satisfied therewith, the person may make such a\ncomplaint to such authority within Sixty days52 after the date of receipt of\nthe land ownership registration certificate. 53\n47 Deleted by the Eighth Amendment.\n48 Amended by the Sixth Amendment.\n49 Amended by the Sixth Amendment.\n50 Inserted by the Sixth Amendment.\n51 Amended by the Eighth Amendment.\n52 Amended by the Eighth Amendment.\n53 Inserted by the Seventh Amendment.\n15\nwww.lawcommission.gov.np\n(3) The prescribed authority shall conduct necessary investigation\ninto the complaints made pursuant to Sub-section (2), check and verify the\nregistration records prepared pursuant to Sub-sections 54 (5), (5a), (5b), 55\n(5c), (5d) and (6) of Section 6 and issue the land ownership registration\ncertificate if it is so required and issue another land ownership registration\ncertificate upon making correction if the land ownership registration\ncertificate is to be so corrected.\nProvided that, if, in investigating into a complaint pursuant to this\nSub-section, the land ownership registration certificate cannot be issued or\ncorrected because of a dispute arisen as to the title or ownership or\npossession pursuant to Sub-section (7) of Section 6, the prescribed\nauthority shall immediately issue a slip to the complainant, clearly setting\nout that the land ownership registration certificate can be issued or\ncorrected only after that matter is decided by the court.\n(4) 56 The registration of the government land or public land shall be\nmade as prescribed.\n8A. 57 Cancellation of registration records upon receipt of details: The\nconcerned General Survey Office or Survey Office shall submit the details\nrelating to the survey and measurement within One Hundred Twenty days\nafter the date of distribution of the land ownership registration certificates,\nand upon receipt of such details, the previous registration records of survey\nand measurement shall ipso facto be canceled.", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "9", "title": "58 Recovery of expenses of survey and measurement: Expenses", "content": "incurred in the survey and measurement of land conducted for the purpose\n54 Amended by the Fourth Amendment.\n55 Inserted by the Seventh Amendment.\n56 Amended by the Sixth Amendment.\n57 Amended by the Eighth Amendment.\n58 Amended by the First Amendment.\n16\nwww.lawcommission.gov.np\nof collection of revenues of the Government shall not be recovered from the\npublic.\nProvided that, the expenses incurred in the survey and measurement\nof land conducted for the purpose of any person himself or herself may be\nrecovered in full from that person.\n9A. 59 Compensation to be paid: If any control point station is set up on any\nland, compensation as prescribed shall be paid to the landholder and tenant\nof that land.\n9B. 60 General responsibilities of landholders and tenants: (1) The tenant,\nif any, of the land on which the control point station is set up and failing\nsuch a tenant, the landholder shall do all reasonable acts to safeguard the\ncontrol point station.\n(2) If, except as a result of an act of God, the control point station\nsustains any loss or damage in any manner or is shifted, demolished or\ndestroyed, the person who has responsibility pursuant to Sub-section (1)\nshall, unless otherwise proved, be deemed to have caused loss or damage\nto, shifted, demolished or destroyed the control point station.", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "10", "title": "61 Categorization of grade of land: In conducting survey and", "content": "measurement of lands, the grades of lands shall be categorized on the basis\nof the prescribed grounds.\n10A.62 Land revenue office to perform functions of Jimidari, Patuwari:\nThe land revenue office shall perform the functions to be performed by\nJimidari, Patuwari following the cancellation of such functionary.\n59 Inserted by the Second Amendment.\n60 Inserted by the Second Amendment.\n61 Amended by the Eighth Amendment.\n62 Amended by the Eighth Amendment.\n17\nwww.lawcommission.gov.np", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "11", "title": "63 To maintain maps and records: (1) In making survey and measurement", "content": "of lands, the maps of lands shall be prepared in the form as specified by the\nDirector General of the Department of Survey. 64\n(2) In making survey and measurement of lands, the records of lands\nshall be prepared and updated as prescribed. 65\n………………66\n11A. 67……………\n11B. 68 Power of Government of Nepal to form committee: If it appears\nthat a survey officer or prescribed authority69 has done any act in\ncontravention of this Act or the rules framed hereunder or that the boundary\nof a forest, government land, public land or trust land have been encroached\nupon or it appears that there has arisen any ordinary problem in relation to\nregistration upon survey and measurement, the Government of Nepal may\nform a committee to rectify or resolve such an act or problem. The\nfunctions, duties and powers of the committee so formed70 shall be\nspecified at the time of its formation.71\n11C.72Power to make survey and measurement for plotting or integrated\ndevelopment: The Government of Nepal may make, or cause to be made,\nsurvey and measurement for the plotting or integrated development of any\nprivate, governmental or public lands.\n63 Amended by the Third Amendment.\n64 Amended by the Sixth Amendment.\n65 Amended by the Sixth Amendment.\n66 Proviso deleted by the Seventh Amendment.\n67 Deleted by the Eighth Amendment.\n68 Inserted by the Third Amendment.\n69 Amended by the Seventh Amendment.\n70 Inserted by the Sixth Amendment.\n71 Amended by the Eighth Amendment.\n72 Inserted by the Eighth Amendment.\n18\nwww.lawcommission.gov.np\n11D.73 Aerial survey, map publication etc. may be made by obtaining\napproval: Notwithstanding anything contained in the other Sections of\nthis Act, if any person, other than the prescribed authority, wishes to make\nan aerial survey, use the control stations set up by the Government of\nNepal, publish maps prepared by the Government of Nepal or sell maps\npublished abroad within ……Nepal74 such a person may do so, subject to\nthe observance of the prescribed terms and conditions.\nProvided that, no map published in aboard shall be sold in Nepal if it\ncontradicts with the map prepared by Government of Nepal.\n11E. 75 Power to give permission to make survey and mapping: (1) The\nGovernment of Nepal may give permission to any person or body to carry\nout acts of survey and mapping as prescribed, subject to the survey and\nmeasurement made pursuant to this Act.\n(2) The matters relating to the fees leviable for the issuance of\npermission pursuant to Sub-section (1), the terms and conditions to be\nobserved by the permission holder person or body and other relevant\nmatters shall be as prescribed.", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "12", "title": "Penalties: (1) If, in making survey and measurement or setting up control", "content": "point stations, any person obstructs, or causes someone to obstruct, the\nsurvey and measurement of land or setting up of such stations by\ndisfiguring fences or signals, instigating people or manhandling or\notherwise, the prescribed authority may punish such a person making such\nobstruction with a fine of up to Fifty Rupees for the first time, of Fifty to\nOne Hundred Rupees for the second time and of One Hundred to Five\n73 Inserted by the Eighth Amendment.\n74\nAmended by the Republic Strengthening and Some Nepal Laws Amendment Act, 2066.\n75 Inserted by the Eighth Amendment.\n19\nwww.lawcommission.gov.np\nHundred Rupees for the third time or with imprisonment for a term of Six\nmonths or with both.\n(2) If a person is held to have made a false complaint that there is\nany kind of alternation in the land surveyed and measured pursuant to\nSection 8, the prescribed authority may punish such a person making such\nfalse complaint with a fine of up to One Hundred Rupees.\n(3) 76 The chief of Land Revenue Office 77 may fine the Jimidar who\ndoes not prepare and submit records within the time-limit pursuant to\nSection 3A. with up to Five Hundred Rupees, the Patuwari who does not\nprepare and submit the same within the said time-limit with up to Three\nHundred Rupees or the Jimidar or Patuwari who does not appear or send\nhis or her representative with up to Five Hundred Rupees for the absence of\neach day.\n(4) 78 If any person shifts, demolishes or destroys or otherwise\ndamages a control point station without the approval of the Department of\nSurvey, the prescribed authority may recover the amount of such damages\nas well as the costs involved in the re-installation or repair of the control\npoint station and also fine such a person with up to One Thousand Rupees.\nThe prescribed authority may recover the amount of expenses incurred\nfrom the false complaint from the person who makes such false complaints\nin this respect and fine such a person with up to Five Hundred Rupees.\n(5) 79 If any person does any act or action without obtaining\npermission pursuant to Section 11D., the prescribed authority may fine such\na person with up to Twenty Thousand Rupees and all surveys and maps as\n76 Inserted by the Second Amendment.\n77 Amended by the Eighth Amendment.\n78 Inserted by the Second Amendment.\n79 Inserted by the Eighth Amendment.\n20\nwww.lawcommission.gov.np\nwell as other materials related with the action or act done or taken without\nobtaining permission shall be confiscated.\n(6) 80 If any person does any other act or action in contravention of\nthis Act, the prescribed authority may fine such a person with up to Ten\nThousand Rupees.", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "13", "title": "81 Appeal: A person who is not satisfied with a decision made by the", "content": "authority prescribed under Section 12 or the chief of Land Revenue Office82\nmay file an appeal to the concerned Court of Appeal 83within Thirty Five\ndays after the date of such decision.", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "14", "title": "Power to frame Rules: The Government of Nepal may frame rules in", "content": "order to implement the objects of this Act.", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "15", "title": "Validity of acts or actions done or taken previously: Any acts or", "content": "actions required to be done or taken pursuant to this Act or the Rules\nframed hereunder prior to the commencement of this Act shall be deemed\nto have been done or taken under this Act.", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "16", "title": "Repeal: For the purposes of this Act, numbers 7, 8, 9 and 10 of land", "content": "Goshowara of the Muluki Ain (General Code) and Nepal law relating to\nsurvey and measurement of lands shall be deemed to have been repealed.\n80 Inserted by the Eighth Amendment.\n81 Amended by the Second Amendment.\n82 Amended by the Eighth Amendment.\n83 Amended by the Administration of Justice Act, 2048..\n21", "children": []}]}]$CODEx83f47c867b$::jsonb,$CODEx5bac142cf7$Land (Survey and Measurement) Act, 2019.pdf$CODEx5bac142cf7$) ON CONFLICT (id) DO UPDATE SET title=EXCLUDED.title, original_title=EXCLUDED.original_title, document_type=EXCLUDED.document_type, year_bs=EXCLUDED.year_bs, year_ad=EXCLUDED.year_ad, total_pages=EXCLUDED.total_pages, nodes=EXCLUDED.nodes, source_filename=EXCLUDED.source_filename;
